//! Tauri backend for the PCB Toolkit desktop app.
//!
//! The whole GUI is schema-driven: the frontend owns a declarative description of every
//! calculator (fields, units, defaults) and sends `{ id, params }` to a single
//! `calculate` command. This keeps adding a calculator to a data change on both sides
//! rather than a new command plus new plumbing.
//!
//! Input structs in `pcb-toolkit` deliberately do not derive `Deserialize`, and several
//! entry points take positional arguments rather than a struct, so this layer reads
//! parameters out of a JSON object by name via `Params`. Every result type *does*
//! derive `Serialize`, so results go back untouched.

use serde::Serialize;
use serde_json::{Value, json};

use pcb_toolkit::wire_gauge::Awg;
use pcb_toolkit::{
    crosstalk, current, differential, fusing, impedance, inductor, materials, ohms_law, padstack,
    pdn, ppm, reactance, resistance, signal, spacing, thermal, via, wavelength, wire_gauge, wires,
};

/// Typed accessor over the JSON parameter object sent by the frontend.
struct Params(Value);

impl Params {
    fn get(&self, key: &str) -> Option<&Value> {
        self.0.get(key)
    }

    /// Required, finite number. Accepts a JSON number, or a numeric string (the inputs are
    /// text fields, and an empty one is reported as a missing value rather than a parse
    /// error).
    ///
    /// The finite check is here rather than only in the library because `f64::from_str`
    /// accepts "nan", "inf", "Infinity" and their signed and mixed-case variants, so without
    /// it typing `nan` into any field in the app reached a calculator. The library rejects it
    /// too (`CalcError::NotFinite`); this gives the GUI a message naming the field, in one
    /// place, for all 50 calculators.
    fn f64(&self, key: &str) -> Result<f64, String> {
        let value = match self.get(key) {
            Some(Value::Number(n)) => n
                .as_f64()
                .ok_or_else(|| format!("`{key}` is not a number"))?,
            Some(Value::String(s)) if !s.trim().is_empty() => s
                .trim()
                .parse::<f64>()
                .map_err(|_| format!("`{key}`: `{s}` is not a number"))?,
            _ => return Err(format!("`{key}` is required")),
        };
        if !value.is_finite() {
            return Err(format!("`{key}` must be a finite number"));
        }
        Ok(value)
    }

    /// True when `key` was not supplied at all — absent, null, or blank.
    ///
    /// The distinction [`Self::f64_or`] needs: "you left this empty, use the default" is not
    /// the same as "what you typed is not a number".
    fn is_absent(&self, key: &str) -> bool {
        match self.get(key) {
            Some(Value::String(s)) => s.trim().is_empty(),
            Some(Value::Null) | None => true,
            _ => false,
        }
    }

    /// Optional number with a default, which applies **only** when the field is empty.
    ///
    /// This used to be `self.f64(key).unwrap_or(default)`, which swallowed parse failures as
    /// well as absence — so typing `4..6` into a dielectric-constant field silently computed
    /// with 4.6 and showed a result that looked fine. A wrong number presented confidently is
    /// the worst outcome available here, so an unparsable value is now an error and only a
    /// blank field takes the default.
    fn f64_or(&self, key: &str, default: f64) -> Result<f64, String> {
        if self.is_absent(key) {
            return Ok(default);
        }
        self.f64(key)
    }

    /// Optional number — absent, null, or blank all mean "not supplied".
    ///
    /// Unlike [`Self::f64_or`], a value that is present but unparsable is still an error
    /// rather than `None`, for the same reason.
    fn opt_f64(&self, key: &str) -> Result<Option<f64>, String> {
        if self.is_absent(key) {
            return Ok(None);
        }
        self.f64(key).map(Some)
    }

    fn u32(&self, key: &str) -> Result<u32, String> {
        let v = self.f64(key)?;
        if v < 0.0 || v.fract() != 0.0 {
            return Err(format!("`{key}` must be a whole number"));
        }
        Ok(v as u32)
    }

    fn bool_or(&self, key: &str, default: bool) -> bool {
        match self.get(key) {
            Some(Value::Bool(b)) => *b,
            Some(Value::String(s)) => s == "true",
            _ => default,
        }
    }

    fn str_or<'a>(&'a self, key: &str, default: &'a str) -> &'a str {
        match self.get(key) {
            Some(Value::String(s)) if !s.is_empty() => s.as_str(),
            _ => default,
        }
    }

    /// A list of numbers, accepted either as a JSON array or as a comma/whitespace
    /// separated string (the component-list inputs are free text).
    fn f64_list(&self, key: &str) -> Result<Vec<f64>, String> {
        let parse_str = |s: &str| -> Result<Vec<f64>, String> {
            let out: Result<Vec<f64>, String> = s
                .split(|c: char| c == ',' || c.is_whitespace())
                .filter(|t| !t.is_empty())
                .map(|t| {
                    t.parse::<f64>()
                        .map_err(|_| format!("`{t}` is not a number"))
                })
                .collect();
            out
        };
        match self.get(key) {
            Some(Value::Array(a)) => a
                .iter()
                .map(|v| match v {
                    Value::Number(n) => n.as_f64().ok_or_else(|| "not a number".to_string()),
                    Value::String(s) => s
                        .trim()
                        .parse::<f64>()
                        .map_err(|_| format!("`{s}` is not a number")),
                    _ => Err("not a number".to_string()),
                })
                .collect(),
            Some(Value::String(s)) => parse_str(s),
            _ => Err(format!("`{key}` is required")),
        }
    }
}

/// Parse an enumerated input using the library's own `FromStr`, so the GUI and the CLI accept
/// exactly the same spellings. These were six hand-written helpers until the parsers moved into
/// the library.
fn parse_enum<T: std::str::FromStr<Err = pcb_toolkit::CalcError>>(s: &str) -> Result<T, String> {
    s.parse::<T>().map_err(|e| e.to_string())
}

