    /// Every dispatch arm resolves, runs, and returns the field the UI reads.
    #[test]
    fn every_calculator_dispatches_and_returns_its_primary_output() {
        for (id, params, key) in cases() {
            let out = calculate(id.to_string(), params.clone())
                .unwrap_or_else(|e| panic!("`{id}` failed: {e}"));
            let v = out
                .get(key)
                .unwrap_or_else(|| panic!("`{id}` result has no `{key}`: {out}"));
            assert!(
                v.is_number(),
                "`{id}` field `{key}` should be numeric, got {v}"
            );
        }
    }

    /// The frontend schema is the third copy of the id list, and the only one that used to
    /// go unchecked.
    ///
    /// `calculators.ts` drives the whole UI, so an id present there and absent from the
    /// dispatch surfaces as "unknown calculator `x`" in the results pane at runtime — and an
    /// id added to the backend but not the schema is simply unreachable. Reading the file
    /// with `include_str!` turns both into a compile-time-ish failure here.
    ///
    /// The scan is deliberately dumb (find `id: "`, take to the closing quote) rather than a
    /// regex dependency: the schema is generated by hand in a fixed shape, and a parser
    /// clever enough to be wrong is not wanted in a test whose whole job is to be obviously
    /// right.
    #[test]
    fn schema_ids_match_the_calculator_id_list() {
        const SCHEMA: &str = include_str!("../../../pcb-app/src/schema/calculators.ts");

        let mut from_schema = Vec::new();
        for (_, after) in SCHEMA
            .match_indices("id: \"")
            .map(|(i, m)| (i, &SCHEMA[i + m.len()..]))
        {
            let Some(end) = after.find('"') else { continue };
            from_schema.push(&after[..end]);
        }

        assert!(
            from_schema.len() > 40,
            "only found {} ids in calculators.ts — has the file's shape changed?",
            from_schema.len()
        );

        let schema: std::collections::BTreeSet<&str> = from_schema.iter().copied().collect();
        assert_eq!(
            from_schema.len(),
            schema.len(),
            "duplicate id in calculators.ts"
        );

        let declared: std::collections::BTreeSet<&str> = CALCULATOR_IDS.iter().copied().collect();
        let missing_from_schema: Vec<&&str> = declared.difference(&schema).collect();
        let missing_from_backend: Vec<&&str> = schema.difference(&declared).collect();
        assert!(
            missing_from_schema.is_empty() && missing_from_backend.is_empty(),
            "calculators.ts and CALCULATOR_IDS disagree.\n  \
             in the backend but not the schema (unreachable from the UI): {missing_from_schema:?}\n  \
             in the schema but not the backend (would show \"unknown calculator\"): {missing_from_backend:?}"
        );
    }

    /// `cases()` must cover exactly the ids in [`CALCULATOR_IDS`], once each.
    ///
    /// This is the guard that used to be `assert_eq!(cases().len(), 37)` — a bare count under
    /// the name `covers_every_dispatch_arm`, which is not what it checked. Rust cannot
    /// enumerate the arms of a `match` at runtime, so nothing can literally prove the dispatch
    /// has no unlisted arm. What this *does* establish, combined with
    /// `every_calculator_dispatches_and_returns_its_primary_output` and
    /// `schema_ids_match_the_calculator_id_list`, is that every id the UI can send resolves
    /// and returns its primary output — and an unlisted arm is unreachable from the UI,
    /// because the UI only ever sends ids from `calculators.ts`.
    #[test]
    fn cases_match_the_calculator_id_list() {
        let ids: Vec<&str> = cases().iter().map(|(id, _, _)| *id).collect();
        let from_cases: std::collections::BTreeSet<&str> = ids.iter().copied().collect();
        assert_eq!(ids.len(), from_cases.len(), "duplicate id in cases()");

        let declared: std::collections::BTreeSet<&str> = CALCULATOR_IDS.iter().copied().collect();
        assert_eq!(
            CALCULATOR_IDS.len(),
            declared.len(),
            "duplicate id in CALCULATOR_IDS"
        );

        let untested: Vec<&&str> = declared.difference(&from_cases).collect();
        let unlisted: Vec<&&str> = from_cases.difference(&declared).collect();
        assert!(
            untested.is_empty() && unlisted.is_empty(),
            "cases() and CALCULATOR_IDS disagree — add new calculators to both.\n  \
             in CALCULATOR_IDS but untested: {untested:?}\n  \
             tested but not declared: {unlisted:?}"
        );
    }

    #[test]
    fn unknown_id_is_an_error() {
        assert!(calculate("nope".into(), json!({})).is_err());
    }

    #[test]
    fn missing_required_parameter_is_reported_by_name() {
        let err = calculate("impedance.microstrip".into(), json!({ "height": 5 })).unwrap_err();
        assert!(err.contains("width"), "error should name the field: {err}");
    }

    /// Library errors surface as readable strings rather than being swallowed.
    ///
    /// This used to drive `impedance.stripline` with a 100 mil trace on a 20 mil height and
    /// assert "unphysical", because the old single-branch IPC-2141 form drove its logarithm
    /// negative there. `impedance::stripline` is now Cohn's two-branch model, whose
    /// wide-trace branch has no logarithm of the geometry to go negative — that cross-section
    /// is a legitimate 14.6 Ω line and no longer an error. The geometry here is a wire
    /// resting on its reference plane, where `4h <= d` makes `ln(4h/d)` non-positive and the
    /// shared post-condition in `impedance::common::finish` rejects it.
    ///
    /// Worth recording how this was found: the test had never been *executed*. This crate
    /// could not link on the development machine, and there was no CI, so rewriting stripline
    /// updated the library's own test and left this one stale and invisible.
    #[test]
    fn library_errors_propagate() {
        let err = calculate(
            "wires.round".into(),
            json!({"diameter":100,"height":25,"er":1.0}),
        )
        .unwrap_err();
        assert!(err.contains("unphysical"), "unexpected error: {err}");
    }

    /// The cross-section the previous version of the test above used must now *succeed*.
    ///
    /// Pinning it from this side too, so the stripline rewrite cannot be quietly reverted
    /// into a state where a wide trace errors again.
    #[test]
    fn a_wide_stripline_trace_is_physical() {
        let out = calculate(
            "impedance.stripline".into(),
            json!({"width":100,"height":20,"thickness":1.4,"er":4.6}),
        )
        .expect("a wide trace is a valid low-impedance line, not an error");
        let zo = out.get("zo").and_then(|v| v.as_f64()).expect("zo");
        assert!(zo > 0.0 && zo < 25.0, "zo = {zo}");
    }

    /// Numeric strings are accepted, since the inputs are text fields.
    #[test]
    fn numeric_strings_are_accepted() {
        let out = calculate(
            "thermal".into(),
            json!({"r_theta_ja":"50","power_w":"2","t_ambient_c":"25"}),
        )
        .unwrap();
        assert_eq!(out["t_junction_c"], json!(125.0));
    }

    #[test]
    fn reference_lists_are_populated() {
        assert_eq!(list_materials().len(), 45);
        assert_eq!(list_awg().len(), 44);
        assert!(list_awg().contains(&"4/0"));
    }
